function xpHash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(16).padStart(8,"0")}
const xpEvoSel=e=>`${e.id}|${e.res}|${e.data}|${e.hora||""}|${e.cat}|${e.prof||""}|${e.texto}`;
{const orig=evoMutate;
 evoMutate=function(fn){
  const antes=new Set(evoAll().map(e=>e.id));
  const wrap=l=>{const novo=fn(l);return novo.map(e=>antes.has(e.id)||e.ass?e:{...e,ass:{por:(typeof f4Quem==="function"&&f4Quem())||e.prof||"",em:new Date().toISOString(),h:xpHash(xpEvoSel(e))}})};
  return orig.call(this,wrap)};}
xmReg("pres","assin","Evolução","Assinaturas e integridade",()=>{
  const L=evoAll().filter(e=>e.ass).sort((a,b)=>b.ass.em.localeCompare(a.ass.em)),alt=L.filter(e=>xpHash(xpEvoSel(e))!==e.ass.h);
  return f6Card("Assinatura eletrônica das evoluções",`Cada evolução nova recebe a identificação de quem registrou, data/hora e um código de integridade. ${L.length} assinada(s); ${alt.length?`<b style="color:#c62828">${alt.length} com conteúdo diferente do assinado</b>`:"nenhuma alterada depois de assinada"}. É um controle interno, não uma assinatura com certificado digital.`,L.length?f6Tbl(["Registro","Residente","Assinado por","Em","Código","Integridade"],[L.slice(0,80).map(e=>`<tr><td>${brDate(e.data)} ${e.hora||""} · ${f6Esc(e.cat)}</td><td>${f6Esc(xmResNome(e.res))}</td><td>${f6Esc(e.ass.por)}</td><td class="n">${brDate(e.ass.em.slice(0,10))} ${e.ass.em.slice(11,16)}</td><td class="n">${e.ass.h}</td><td>${xpHash(xpEvoSel(e))===e.ass.h?f6Dot("#2e7d32")+"íntegro":f6Dot("#c62828")+"alterado"}</td></tr>`).join("")],"txt"):`<div class="empty">Ainda não há evoluções assinadas (valem as feitas a partir de agora).</div>`);
});
