const xpDir=xmFicha({mod:"pres",key:"diretivas",titulo:"Cuidados paliativos e diretivas antecipadas de vontade",sub:"O que a pessoa e a família decidiram sobre tratamentos. Registre fielmente e guarde o documento assinado.",campos:[{k:"pal",l:"Em cuidados paliativos",t:"check"},{k:"pref",l:"Preferências de tratamento (hospitalização, intubação, alimentação por sonda…)",t:"textarea"},{k:"decide",l:"Quem decide quando a pessoa não puder"},{k:"doc",l:"Documento assinado existe",t:"check"},{k:"docloc",l:"Onde está guardado o documento"},{k:"data",l:"Data da decisão",t:"date"},{k:"rel",l:"Preferências espirituais e religiosas"},{k:"obs",l:"Outras orientações"}]});
xmReg("pres","diretivas","Cadastro clínico","Cuidados paliativos e diretivas",xpDir.html,xpDir.bind);
const xpMed=xmFicha({mod:"pres",key:"medresp",titulo:"Médico responsável, hospital e plano de saúde",campos:[{k:"medico",l:"Médico responsável"},{k:"crm",l:"CRM"},{k:"tel",l:"Telefone do médico"},{k:"hosp",l:"Hospital de preferência"},{k:"plano",l:"Plano de saúde"},{k:"cart",l:"Nº da carteirinha"},{k:"val",l:"Validade da carteirinha",t:"date"},{k:"samu",l:"Instruções para emergência",t:"textarea"}]});
xmReg("pres","medresp","Cadastro clínico","Médico e plano de saúde",xpMed.html,xpMed.bind);
xmUrg(()=>podeVer("pres")?Object.entries(xpMed.get()).filter(([id,d])=>d.val&&xmDias(d.val)<=30&&resAll().some(r=>r.id===id&&resAtivo(r))).map(([id,d])=>({nivel:xmDias(d.val)<0?2:1,tipo:"Saúde",titulo:`Carteirinha do plano ${xmDias(d.val)<0?"vencida":"vencendo"}: ${xmResNome(id)}`,detalhe:brDate(d.val),quando:d.val,rota:"pres"})):[]);


